def transform(g):
    H,W=len(g),len(g[0])
    o=[row[:] for row in g]
    # fit p and S from interior nonzero cells
    for p in range(2,15):
        votes={}
        for r in range(3,H):
            for c in range(3,W):
                if g[r][c]:
                    votes.setdefault((r+c)%p,{}).setdefault(g[r][c],0)
                    votes[(r+c)%p][g[r][c]]+=1
        if len(votes)==p and all(len(v)>1 or True for v in votes.values()):
            S={k:max(v.items(),key=lambda x:x[1])[0] for k,v in votes.items()}
            bad=sum(1 for r in range(3,H) for c in range(3,W) if g[r][c] and g[r][c]!=S[(r+c)%p])
            if bad<=8: break
    for r in range(H):
        for c in range(W):
            if o[r][c]==0:
                if r<2 or c<2: o[r][c]=1
                elif r==2 or c==2: o[r][c]=4
                else: o[r][c]=S[(r+c)%p]
    return o
